#!/usr/bin/env python3

"""Generate Vally eval specs from the reviewer eval governance manifests."""

import argparse
import json
import shutil
import sys
from pathlib import Path
from typing import Any


REPO_ROOT = Path(__file__).resolve().parents[4]
REVIEWER_EVALS = (
    REPO_ROOT / ".github/skills/aspnetcore-pr-review/evals/evals.json"
)
TRY_FIX_EVALS = (
    REPO_ROOT / ".github/skills/aspnetcore-try-fix/evals/evals.json"
)
VALLY_ROOT = REPO_ROOT / "eng/skill-evals"
VALLY_PACKAGE = "@microsoft/vally-cli@0.13.0"
SANITIZED_SOURCE_PATHS = [
    "eng/skill-evals/aspnetcore-pr-review",
    "eng/skill-evals/aspnetcore-try-fix",
]
COMMON_SOURCE_PATHS = [
    ".github/instructions",
    "eng",
    "src/Shared",
    ".editorconfig",
    ".gitignore",
    ".globalconfig",
    "activate.ps1",
    "activate.sh",
    "AspNetCore.slnx",
    "Directory.Build.BeforeCommonTargets.targets",
    "Directory.Build.props",
    "Directory.Build.targets",
    "global.json",
    "NuGet.config",
    "restore.cmd",
    "restore.sh",
]
AREA_SOURCE_PATHS = {
    "Components": "src/Components",
    "Hosting": "src/Hosting",
    "Http": "src/Http",
    "MVC": "src/Mvc",
    "Servers": "src/Servers",
    "SignalR": "src/SignalR",
    "Testing": "src/Testing",
}
MAIN_OUTPUTS = {
    "aspnetcore-pr-review": VALLY_ROOT
    / "aspnetcore-pr-review/regression.vally.yaml",
    "aspnetcore-try-fix": VALLY_ROOT
    / "aspnetcore-try-fix/regression.vally.yaml",
}
MODEL_GUARDRAIL_OUTPUT = (
    VALLY_ROOT / "aspnetcore-pr-review/model-guardrail.vally.yaml"
)
MODEL_GUARDRAIL_MECHANISM = "orchestrator-model-guardrail"
STAGED_SKILL_FILES = {
    "aspnetcore-pr-review": [
        Path("SKILL.md"),
        Path("references/proof-calibration.md"),
        Path("scripts/validate_artifacts.py"),
    ],
    "aspnetcore-try-fix": [
        Path("SKILL.md"),
    ],
}


def yaml_string(value: str) -> str:
    return json.dumps(value, ensure_ascii=True)


def append_literal(lines: list[str], key: str, value: str, indent: int) -> None:
    prefix = " " * indent
    lines.append(f"{prefix}{key}: |-")
    for line in value.splitlines() or [""]:
        lines.append(f"{prefix}  {line}" if line else "")


def eval_name(eval_data: dict[str, Any]) -> str:
    mechanism = eval_data["eval_metadata"]["mechanism"]
    return f"eval-{eval_data['id']:02d}-{mechanism}"


def append_file_overlay(
    lines: list[str], source: str, destination: str, indent: int
) -> None:
    prefix = " " * indent
    lines.append(
        f"{prefix}- src: {yaml_string('../../../' + source)}"
    )
    lines.append(f"{prefix}  dest: {yaml_string(destination)}")


def render_environment(
    lines: list[str], eval_data: dict[str, Any], indent: int
) -> None:
    prefix = " " * indent
    area_root = eval_data["eval_metadata"]["area"].split("/", 1)[0]
    area_source = AREA_SOURCE_PATHS.get(area_root)
    files = eval_data["files"]
    if area_source is None and not files:
        return

    lines.append(f"{prefix}environment:")
    lines.append(f"{prefix}  files:")
    if area_source is not None:
        append_file_overlay(
            lines,
            area_source,
            area_source,
            indent + 4,
        )
    for index, file_path in enumerate(files, start=1):
        append_file_overlay(
            lines,
            file_path,
            f"eval-input/fixture-{index}.md",
            indent + 4,
        )


def projected_prompt(eval_data: dict[str, Any]) -> str:
    prompt = eval_data["prompt"]
    if eval_data["files"]:
        fixture_list = "\n".join(
            f"- eval-input/fixture-{index}.md"
            for index, _ in enumerate(eval_data["files"], start=1)
        )
        prompt = f"{prompt}\n\nFixture files:\n{fixture_list}"

    prompt_lower = prompt.casefold()
    leaked_terms = [
        term
        for term in eval_data["eval_metadata"]["forbidden_prompt_terms"]
        if term.casefold() in prompt_lower
    ]
    if leaked_terms:
        raise ValueError(
            f"eval {eval_data['id']} projected prompt leaks forbidden terms: "
            + ", ".join(leaked_terms)
        )
    return prompt


def render_eval_spec(
    document: dict[str, Any],
    source_path: Path,
    evals: list[dict[str, Any]],
    *,
    model: str,
) -> str:
    skill_name = document["skill_name"]
    source = source_path.relative_to(REPO_ROOT).as_posix()
    lines = [
        f"# Generated by {Path(__file__).relative_to(REPO_ROOT).as_posix()}.",
        f"# Source of truth: {source}.",
        f"# Validated with {VALLY_PACKAGE}.",
        "# Run the generator with --check to detect drift.",
        f"name: {skill_name}",
        f"description: {yaml_string(f'Vally evals for the {skill_name} skill.')}",
        "type: capability",
        "defaults:",
        "  runs: 5",
        "  timeout: 1200s",
        f"  model: {model}",
        "  judge_model: claude-opus-5",
        "environment:",
        "  files:",
    ]
    for source_path in COMMON_SOURCE_PATHS:
        append_file_overlay(lines, source_path, source_path, 4)
    lines.extend(
        [
        "  commands:",
        "    - git init --quiet",
        "    - git clean -fdX",
        (
            "    - git clean -fd -- "
            + " ".join(SANITIZED_SOURCE_PATHS)
        ),
        (
            "    - git remote add origin "
            "https://github.com/dotnet/aspnetcore.git"
        ),
        (
            "    - git remote set-url --push origin "
            "no-push://dotnet/aspnetcore"
        ),
        "    - git add .",
        (
            "    - git -c user.name=Vally "
            "-c user.email=vally@example.invalid "
            'commit --quiet --allow-empty -m "Vally fixture"'
        ),
        "scoring:",
        "  weights:",
        "    prompt: 1.0",
        "  threshold: 0.7",
        "stimuli:",
        ]
    )

    for eval_data in evals:
        metadata = eval_data["eval_metadata"]
        provenance = metadata["provenance"]
        grader_threshold = (
            1.0
            if metadata["mechanism"] == MODEL_GUARDRAIL_MECHANISM
            else 0.7
        )
        lines.append(f"  - name: {yaml_string(eval_name(eval_data))}")
        append_literal(lines, "prompt", projected_prompt(eval_data), 4)
        lines.extend(
            [
                "    tags:",
                f"      eval_id: {yaml_string(str(eval_data['id']))}",
                f"      skill_name: {yaml_string(skill_name)}",
                f"      executor_model: {yaml_string(model)}",
                '      expected_runs: "5"',
                f"      area: {yaml_string(metadata['area'])}",
                f"      score_family: {yaml_string(metadata['score_family'])}",
                f"      tier: {yaml_string(metadata['tier'])}",
                (
                    "      provenance_kind: "
                    f"{yaml_string(provenance['kind'])}"
                ),
                (
                    "      provenance_source: "
                    f"{yaml_string(provenance['source'])}"
                ),
                (
                    "      discovery_mode: "
                    f"{yaml_string(metadata['discovery_mode'])}"
                ),
            ]
        )
        render_environment(lines, eval_data, 4)
        lines.extend(
            [
                "    graders:",
                "      - type: prompt",
                "        config:",
                f"          threshold: {grader_threshold}",
                "    rubric:",
                (
                    "      - "
                    + yaml_string(
                        "Overall response matches this expected outcome: "
                        + eval_data["expected_output"]
                    )
                ),
            ]
        )
        for expectation in eval_data["expectations"]:
            lines.append(f"      - {yaml_string(expectation)}")

    return "\n".join(lines) + "\n"


def load_document(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def expected_outputs() -> dict[Path, str]:
    reviewer = load_document(REVIEWER_EVALS)
    try_fix = load_document(TRY_FIX_EVALS)
    reviewer_main = [
        eval_data
        for eval_data in reviewer["evals"]
        if eval_data["eval_metadata"]["mechanism"]
        != MODEL_GUARDRAIL_MECHANISM
    ]
    reviewer_guardrail = [
        eval_data
        for eval_data in reviewer["evals"]
        if eval_data["eval_metadata"]["mechanism"]
        == MODEL_GUARDRAIL_MECHANISM
    ]

    return {
        MAIN_OUTPUTS["aspnetcore-pr-review"]: render_eval_spec(
            reviewer,
            REVIEWER_EVALS,
            reviewer_main,
            model="gpt-5.6-sol",
        ),
        MODEL_GUARDRAIL_OUTPUT: render_eval_spec(
            reviewer,
            REVIEWER_EVALS,
            reviewer_guardrail,
            model="claude-sonnet-5",
        ),
        MAIN_OUTPUTS["aspnetcore-try-fix"]: render_eval_spec(
            try_fix,
            TRY_FIX_EVALS,
            try_fix["evals"],
            model="gpt-5.6-sol",
        ),
    }


def check_outputs(outputs: dict[Path, str]) -> list[str]:
    errors: list[str] = []
    for path, expected in outputs.items():
        try:
            actual = path.read_text(encoding="utf-8")
        except OSError as error:
            errors.append(f"{path.relative_to(REPO_ROOT)}: {error}")
            continue
        if actual != expected:
            errors.append(
                f"{path.relative_to(REPO_ROOT)} is out of date; "
                "run sync_vally_evals.py"
            )
    return errors


def stage_skills(output_root: Path) -> None:
    output_root = output_root.resolve()
    forbidden_roots = {
        Path("/").resolve(),
        Path.home().resolve(),
        REPO_ROOT.resolve(),
    }
    if output_root in forbidden_roots or REPO_ROOT.resolve() in output_root.parents:
        raise ValueError(f"refusing unsafe staging root: {output_root}")

    for skill_name, relative_paths in STAGED_SKILL_FILES.items():
        source_root = REPO_ROOT / ".github/skills" / skill_name
        destination_root = output_root / skill_name
        if destination_root.exists():
            shutil.rmtree(destination_root)
        for relative_path in relative_paths:
            source = source_root / relative_path
            destination = destination_root / relative_path
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, destination)


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Generate Vally specs from reviewer eval manifests."
    )
    action = parser.add_mutually_exclusive_group()
    action.add_argument(
        "--check",
        action="store_true",
        help="Fail when checked-in Vally specs differ from generated output.",
    )
    action.add_argument(
        "--stage-skills",
        type=Path,
        metavar="DIRECTORY",
        help="Copy only runtime skill files into a sanitized staging directory.",
    )
    args = parser.parse_args()

    if args.stage_skills is not None:
        try:
            stage_skills(args.stage_skills)
        except (OSError, ValueError) as error:
            print(f"ERROR: unable to stage skills: {error}", file=sys.stderr)
            return 1
        print(f"Staged sanitized skills in {args.stage_skills.resolve()}")
        return 0

    outputs = expected_outputs()
    if args.check:
        errors = check_outputs(outputs)
        if errors:
            for error in errors:
                print(f"ERROR: {error}", file=sys.stderr)
            return 1
        print("Vally eval specs are synchronized.")
        return 0

    for path, content in outputs.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        print(f"Wrote {path.relative_to(REPO_ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
